def phan_loai(thu_nhap, tuoi):
    if thu_nhap < 20:
        if tuoi < 30:
            return "Tiềm năng"
        return "Thường"
    if tuoi < 40:
        return "Cao cấp"
    return "Thường"

khach = [(15, 25), (20, 35), (25, 40), (19, 30)]
ket_qua = []
for thu_nhap, tuoi in khach:
    ket_qua.append(phan_loai(thu_nhap, tuoi))
print(ket_qua)

def gini(p):
    return 1 - (p**2 + (1 - p)**2)

p0 = 4 / 8
result = gini(p0)
print(result)

def predict_label(proba, threshold=0.5):
    if proba > threshold:
        return 'Đạt'
    else:
        return 'Trượt'

probs = [0.29, 0.99]
labels = [predict_label(p) for p in probs]
print(labels)
